sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    // POST /override — human override of the advisory AI recommendation.
    // Body: { case_id, overrides:{...}, reason, user? }
    var agent = new bfd_TriageAgent();
    var body = agent.readBody(request) || {};
    agent.send(
        response,
        agent.overrideRecommendation(body.case_id || body.case_sys_id, body.overrides, body.reason, body.user)
    );
})(request, response);
